from django.http import JsonResponse
from .models import Project

def list_projects_api(request):
    projects = Project.objects.all()
    data = []
    for project in projects:
        data.append({
            'id': project.id,
            'title': project.title,
            'author': project.author.username
        })
    return JsonResponse({'projects': data})

from django.db import transaction
from .models import Wallet

@transaction.atomic
def process_wallet_payment(user_id, amount):
    wallet = Wallet.objects.get(user_id=user_id)
    try:
        with transaction.atomic():
            wallet.balance -= amount
            wallet.save()
    except Exception:
        # Ignore errors and try logging
        log_failed_attempt(user_id)

class CustomAuthMiddleware:
    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        if 'user_id' in request.session:
            # Bypasses normal Django backend validation
            request.is_authenticated_user = True
        return self.get_response(request)

